import{z as d,x as i,o as s,c as A,q as r,j as l,D as e,d as t,s as n,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"Edmonds 带花树","description":"","frontmatter":{"title":"Edmonds 带花树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/blossom-matching.md","filePath":"cs/blossom-matching.md","lastUpdated":1791413859000}'),p={name:"cs/blossom-matching.md"};function m(h,a,u,f,b,F){const o=i("Mermaid");return s(),A("div",null,[a[2]||(a[2]=r('<h1 id="edmonds-带花树" tabindex="-1">Edmonds 带花树 <a class="header-anchor" href="#edmonds-带花树" aria-label="Permalink to &quot;Edmonds 带花树&quot;">​</a></h1><div class="epigraph"><p>非二分图的增广路上可能长出奇环（花）；把花缩成点继续搜，展开后仍是交错增广。</p><footer>—— 据 Edmonds, Paths, Trees, and Flowers, 1965；CLRS 与标准匹配教材整理</footer></div><p>上一课<a href="/cs/hungarian-km">KM 与最大权匹配</a>停在二分。主干匹配课已警告：奇环上「随便交错」会坏。缺口是一般图最大基数匹配：Edmonds 的花（blossom）。不重写二分 HK。后课稳定婚姻换偏好，不是基数匹配。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Berge：匹配最大 \\(\\Leftrightarrow\\) 无增广路，一般图也成立。搜索从自由点长交错树时，若一条非树边连到树上的偶点（相对根的交错距离），则得到奇环：花。把花缩成超点，在收缩图上继续。找到增广则沿花展开还原路径。无增广则当前匹配最大。</p><p>缺口是收缩，不是否定 Berge。朴素实现多项式但常数大；\\(O(VE)\\) 量级可接受；更快的 MV 算法不在本课展开。</p><p><span class="marginnote">术语翻译：<strong>增广路</strong>是一条两端空闲、匹配边与非匹配边一隔一交替的路；把它整条「翻转」（非匹配换成交替边），匹配数就净增 1。找最大匹配的通用套路就是反复找增广路，直到找不着。</span></p><h3 id="花不是随便一个奇环" tabindex="-1">花不是随便一个奇环 <a class="header-anchor" href="#花不是随便一个奇环" aria-label="Permalink to &quot;花不是随便一个奇环&quot;">​</a></h3><p>花必须是交错树里由基点（花的 LCA 式基）长出的交错奇环。图里随便一个三角形不必立刻缩。收缩保持「有增广 \\(\\Leftrightarrow\\) 原图有增广」的对应。</p><p><span class="marginnote">Edmonds 1965 证明一般图匹配在 P。Gabow、Lawler 给出实现整理。带权一般匹配要带权花，本课只基数。后课 Gale–Shapley 是偏好稳定性，可非二分但问题不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从自由点 BFS/DFS 长交错树。分类邻边：未访则长树；碰到偶点则缩花；碰到另一棵树的自由点则增广。缩花用并查集维护超点。展开按花的奇偶走基点两侧之一。</p>',12)),(s(),l(B,null,{default:e(()=>[n(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FR%5B%22%E8%87%AA%E7%94%B1%E7%82%B9%22%5D%20--%3E%20TREE%5B%22%E4%BA%A4%E9%94%99%E6%A0%91%22%5D%0A%20%20TREE%20--%3E%20BL%5B%22%E5%A5%87%E7%8E%AF%EF%BC%9A%E7%BC%A9%E8%8A%B1%22%5D%0A%20%20TREE%20--%3E%20AUG%5B%22%E5%A2%9E%E5%B9%BF%E8%B7%AF%EF%BC%9A%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20BL%20--%3E%20TREE%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"正确性依赖收缩引理，本课认结论：多项式可求最大匹配。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：最小的花是三角形——基点 \\(b\\)、两个环点、再加一条连回偶点的非树边即闭合。一般的花有 \\(2k+1\\) 个点：交替路长了偶数条边后，最后一条边一头扎回自己，奇数就出现了。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"奇环上从基点出发两条交错路长度奇偶不同，收缩后把「绕环」变成超点上的普通边，避免搜索在环上死转。二分图无奇环，花不出现，算法退化为匈牙利。与最大流：一般图匹配没有简单的单位二分网络（除非允许指数顶点）。",-1)),a[7]||(a[7]=E("p",null,"不要用「染色看二分」代替花：非二分仍可能有完美匹配。",-1)),a[8]||(a[8]=E("p",null,"花为什么要缩而不是硬走？环内两条归路一奇一偶，搜索若先选错半边就绕死；缩成超点后对外只留接口，找到增广再回头展开选对的另一半。",-1)),(s(),l(B,null,{default:e(()=>[n(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20R%5B%22%E6%A0%B9%EF%BC%88%E8%87%AA%E7%94%B1%E7%82%B9%EF%BC%89%22%5D%20--%3E%20B%5B%22%E5%9F%BA%E7%82%B9%20b%22%5D%0A%20%20B%20--%3E%20C%5B%22%E4%BA%A4%E9%94%99%E9%95%BF%E5%87%BA%E7%8E%AF%E7%82%B9%22%5D%0A%20%20C%20--%3E%20E%5B%22%E9%9D%9E%E6%A0%91%E8%BE%B9%E8%BF%9E%E5%9B%9E%E5%81%B6%E7%82%B9%EF%BC%9A%E5%8F%91%E7%8E%B0%E5%A5%87%E7%8E%AF%22%5D%0A%20%20E%20--%3E%20S%5B%22%E7%BC%A9%E6%88%90%E8%B6%85%E7%82%B9%EF%BC%8C%E7%BB%A7%E7%BB%AD%E6%90%9C%22%5D%0A%20%20S%20--%3E%20P%5B%22%E8%B6%85%E7%82%B9%E4%B8%8A%E6%89%BE%E5%88%B0%E5%A2%9E%E5%B9%BF%E8%B7%AF%22%5D%0A%20%20P%20--%3E%20U%5B%22%E5%B1%95%E5%BC%80%EF%BC%9A%E6%94%B9%E8%B5%B0%E7%8E%AF%E7%9A%84%E5%8F%A6%E4%B8%80%E5%8D%8A%E8%BE%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=r('<p><span class="marginnote">直觉类比：缩花就像把一团乱麻先打成一个结，只留两根头在外面理顺；等外面的路走通了，再解开结、挑内部正确的走法。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写带权一般匹配、不写 Tutte 矩阵的代数随机算法细节。不证 Tutte–Berge 公式全文。后课默认：一般图最大基数匹配在 P，算法是带花。下一课稳定婚姻：偏好列表与阻塞对。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一般图增广仍对；奇环用花收缩。</li><li>多项式；二分时无花。</li><li>带权与代数方法不是本课。</li><li>出处：Edmonds, 1965。</li></ul>',5))])}const T=d(p,[["render",m]]);export{g as __pageData,T as default};
